<template><AppShell :title="activity?.title||'活动中心'" back><view class="activity-pad"><StateView :loading="loading" :error="error" :count="id?(activity?1:0):activities.length" title="暂无开放活动" description="活动上架后会在这里展示" @retry="load" /><template v-if="!id"><button class="ui-button activity-link" v-for="a in activities" :key="a.id" @click="go('rewards/activity',{id:a.id})"><image :src="rewardImage(a.cover)" mode="aspectFill" /><view class="row between"><text class="bold">{{a.title}}</text><text class="tiny">{{a.pointsCost}} 积分 / 次 ›</text></view></button></template><template v-if="activity"><image v-if="rewardImage(activity.cover)" class="activity-cover" :src="rewardImage(activity.cover)" mode="aspectFill" /><view class="activity-balance row between"><text>可用积分 <text class="bold">{{balance??'—'}}</text></text><button class="ui-button tiny" @click="open('rewards/points')">积分明细 ›</button></view><text v-if="!activity.drawEnabled" class="closed-note">免费积分规则待确认，抽奖暂未开放。</text><view class="wheel-area"><view class="pointer">▼</view><view class="wheel" :style="{transform:'rotate('+rotation+'deg)',background:wheelBackground}"><view class="wheel-label" v-for="(p,i) in activity.prizes" :key="p.id" :style="labelStyle(i)"><text :class="{'muted':!p.available}">{{p.title}}</text></view></view><view class="wheel-center">困困</view></view><view class="draw-buttons"><button class="ui-button btn" :disabled="busy||!activity.drawEnabled" @click="draw(1)">{{busy?'正在核对…':'单抽 · '+activity.pointsCost+' 积分'}}</button><button class="ui-button btn dark" :disabled="busy||!activity.drawEnabled" @click="draw(5)">五连 · {{activity.pointsCost*5}} 积分</button></view><view class="card section" v-if="results.length"><text class="bold">本次结果</text><view class="result-row" v-for="(r,i) in results" :key="i"><text>{{i+1}}. {{r.title}}</text><button v-if="r.orderId" class="ui-button tiny" @click="go('rewards/order',{id:r.orderId})">查看领取 ›</button></view></view><view class="card section"><text class="bold">活动规则</text><text class="rules">{{activity.description}}</text><text class="rules muted">{{activity.rule}}</text><text class="rules muted tiny">{{date(activity.startsAt)}} 至 {{date(activity.endsAt)}} · 按服务器时间</text><view class="odds-row" v-for="p in activity.prizes" :key="p.id"><text>{{p.title}}</text><text>{{p.available?(p.probability*100).toFixed(2)+'%':'当前不可领取'}}</text></view><text class="tiny muted rules">转盘格子大小仅用于展示，当前概率见上表；库存、已持有勋章会使后续抽取概率变化。</text></view><button class="ui-button btn outline section" @click="loadHistory">查看抽奖记录</button><view class="card section" v-for="record in history" :key="record.id"><text class="muted tiny">{{date(record.createdAt)}} · {{record.pointsSpent}} 积分</text><view class="result-row" v-for="(r,i) in record.results" :key="i"><text>{{r.title}}</text><button v-if="r.orderId" class="ui-button tiny" @click="go('rewards/order',{id:r.orderId})">领取 ›</button></view></view><button v-if="history.length<historyTotal" class="ui-button btn outline section" @click="loadHistory(true)">更多记录</button></template><button class="ui-button btn outline section" @click="go('rewards/mall')">逛积分商城</button></view></AppShell></template>
<script setup>
import {ref,computed,watch} from 'vue';import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,session,requireLogin,go,toast,date,loadMe} from '../../lib/api';import {rewardImage,rewardIntent,submitReward,discardRejectedReward} from '../../lib/rewards'
const id=ref(''),activities=ref([]),activity=ref(null),loading=ref(false),error=ref(''),balance=ref(null),busy=ref(false),rotation=ref(0),results=ref([]),history=ref([]),historyTotal=ref(0);let generation=0,historyPage=1,historyBusy=false;onLoad(q=>id.value=q.id||'');onShow(load);onUnload(resetPrivate);watch(()=>session.token,resetPrivate,{flush:'sync'})
function resetPrivate(){generation++;balance.value=null;results.value=[];history.value=[];historyTotal.value=0;historyPage=1;busy.value=false;loading.value=false;historyBusy=false}
const wheelBackground=computed(()=>{const n=activity.value?.prizes?.length||2;return 'conic-gradient(from -'+180/n+'deg,'+Array.from({length:n},(_,i)=>`${i%2?'#fff8d7':'#ffe433'} ${i*360/n}deg ${(i+1)*360/n}deg`).join(',')+')'})
function labelStyle(i){const n=activity.value.prizes.length;return {transform:`translate(-50%,-50%) rotate(${i*360/n}deg) translateY(-96px) rotate(${-i*360/n}deg)`}}
function open(path){if(requireLogin())go(path)}
async function load(){if(busy.value)return;const v=++generation;loading.value=true;error.value='';balance.value=null;try{const r=await request(id.value?'/boost/rewards/activities/'+id.value:'/boost/rewards/activities');if(v!==generation)return;if(id.value)activity.value=r;else activities.value=r.items;if(session.token){const p=await request('/boost/rewards/points');if(v===generation)balance.value=p.balance}}catch(e){if(v===generation)error.value=e.message}finally{if(v===generation)loading.value=false}}
async function draw(count){if(busy.value||!requireLogin())return;const token=session.token,v=generation;let intent;busy.value=true;try{if(!session.user)await loadMe();if(v!==generation||token!==session.token)return;intent=rewardIntent('draw',id.value,{count,expectedPointsCost:activity.value.pointsCost,expectedRevision:activity.value.revision});if(intent.data.count!==count){toast('上次请求尚未确认，请先重试'+(intent.data.count===5?'五连':'单抽'));return}const r=await submitReward(intent,`/boost/rewards/activities/${id.value}/draw`);if(v!==generation||token!==session.token)return;const last=r.results[r.results.length-1],n=activity.value.prizes.length,target=(360-last.position*360/n)%360;rotation.value=rotation.value+(1440+target-rotation.value%360);results.value=r.results;balance.value=r.balance;const current=await request('/boost/rewards/activities/'+id.value);if(v===generation)activity.value=current}catch(e){if(intent)discardRejectedReward(intent,e);if(v===generation&&token===session.token){toast(e.message);if(e.code===409){busy.value=false;load()}}}finally{if(v===generation)busy.value=false}}
async function loadHistory(more=false){if(historyBusy||!requireLogin())return;historyBusy=true;const v=generation;try{const page=more?historyPage+1:1,r=await request('/boost/rewards/draws','GET',{page});if(v===generation){history.value=more?[...history.value,...r.items]:r.items;historyTotal.value=r.total;historyPage=page}}catch(e){toast(e.message)}finally{if(v===generation)historyBusy=false}}
</script>
<style scoped>.activity-pad{padding:16px}.activity-cover{display:block;width:100%;height:150px;border-radius:12px}.activity-link{display:block;text-align:left;background:#fff;width:100%;border-radius:12px;overflow:hidden;margin-bottom:16px}.activity-link image{width:100%;height:160px}.activity-link .row{padding:14px;gap:10px}.activity-balance{margin:18px 0}.closed-note{display:block;padding:12px;background:#fff4d2;border-radius:8px;font-size:12px}.wheel-area{position:relative;margin:25px auto;width:282px;height:282px}.wheel{width:100%;height:100%;border:7px solid #dec147;border-radius:50%;box-sizing:border-box;position:relative;transition:transform 1.8s cubic-bezier(.2,.7,.2,1)}.wheel-label{position:absolute;left:50%;top:50%;width:79px;font-size:11px;text-align:center;font-weight:650;overflow-wrap:anywhere}.pointer{position:absolute;left:calc(50% - 13px);top:-15px;font-size:30px;z-index:3;color:#191919}.wheel-center{position:absolute;left:calc(50% - 29px);top:calc(50% - 29px);height:58px;width:58px;border:4px solid #ffe433;border-radius:50%;background:#191919;color:#ffe433;display:flex;align-items:center;justify-content:center;font-weight:800;box-sizing:border-box}.draw-buttons{display:flex;gap:10px}.draw-buttons .btn{flex:1;padding:0 6px;font-size:13px}.dark{background:#191919;color:#ffe433}.rules{display:block;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:10px}.odds-row,.result-row{display:flex;justify-content:space-between;gap:12px;font-size:12px;padding:10px 0;border-bottom:1px solid #f0f0f0}.odds-row>text:first-child,.result-row>text{overflow-wrap:anywhere}.result-row button{flex-shrink:0}@media(prefers-reduced-motion:reduce){.wheel{transition:none}}@media(max-width:340px){.wheel-area{width:270px;height:270px}}</style>
